import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline
cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation);
"""
cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cstdint>
#include <cute/tensor.hpp>
using namespace cute;
// Structural rewrite + register blocking: CTA-level spatial (output-row x
// output-col) tiling with shared-memory staging of the reusable input
// column tile, PLUS each thread now computes OW_PER_THREAD (>1) output
// columns instead of a single column. This amortizes the per-thread loop
// overhead (oh loop, k loop, index arithmetic) and the shared-memory
// staging cost across more useful FLOPs per thread, increasing arithmetic
// intensity and reducing the number of CTAs needed to cover the width
// dimension, all while keeping the exact same shared-memory reuse pattern
// (each input row staged once per channel and reused across all K taps
// and across all output rows in the OH tile).
//
// Memory-coalescing optimization: each thread's OW_PER_THREAD output
// columns are now made CONTIGUOUS (instead of strided across the whole
// tile). This allows both the global->shared input staging loads and the
// final shared->global output stores to be issued as single 128-bit
// (float4) vectorized memory transactions instead of 4 separate 32-bit
// transactions, cutting instruction count and improving memory
// throughput, while falling back to the original scalar per-element path
// whenever the contiguous vectorized access is not valid (tile edges,
// non-unit stride, or unaligned addresses), preserving exact semantics.
template <typename T>
__global__ void dwconv2d_k1_kernel_tiled(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int K, int stride, int padding, int dilation,
    int Hout, int Wout,
    int OH_TILE, int OW_TILE, int IH_TILE,
    int CTiles, int CcPerBlock, int OW_PER_THREAD)
{
  extern __shared__ unsigned char smem_raw[];
  T* sX = reinterpret_cast<T*>(smem_raw);
  const int ow_local0    = threadIdx.x;
  const int oh_group     = threadIdx.y;
  const int oh_threads   = blockDim.y;
  const int ow_threads   = blockDim.x;
  const int ow_tile_idx  = blockIdx.x;
  const int oh_tile_idx  = blockIdx.y;
  const int zc     = blockIdx.z;
  const int c_tile = zc % CTiles;
  const int n      = zc / CTiles;
  constexpr int MAX_OW_PER_THREAD = 4; // must be >= host-side OW_PER_THREAD
  int ow_local[MAX_OW_PER_THREAD];
  int ow[MAX_OW_PER_THREAD];
  bool valid_ow[MAX_OW_PER_THREAD];
  int iw[MAX_OW_PER_THREAD];
  bool valid_iw[MAX_OW_PER_THREAD];
  #pragma unroll
  for (int i = 0; i < MAX_OW_PER_THREAD; ++i) {
    if (i < OW_PER_THREAD) {
      // Contiguous per-thread output-column mapping: enables vectorized
      // (float4) global/shared-memory accesses since a thread's
      // OW_PER_THREAD columns are now adjacent instead of strided.
      ow_local[i] = ow_local0 * OW_PER_THREAD + i;
      ow[i] = ow_tile_idx * OW_TILE + ow_local[i];
      valid_ow[i] = (ow[i] < Wout);
      if (valid_ow[i]) {
        iw[i] = ow[i] * stride - padding;
        valid_iw[i] = (iw[i] >= 0 && iw[i] < Win);
      } else {
        iw[i] = 0;
        valid_iw[i] = false;
      }
    } else {
      ow_local[i] = 0; ow[i] = 0; valid_ow[i] = false; iw[i] = 0; valid_iw[i] = false;
    }
  }
  // A thread's OW_PER_THREAD input columns are contiguous in the input row
  // only when stride == 1; require full validity so the 4-wide window is
  // safe to read/write as one 128-bit access.
  const bool can_vec4 = (OW_PER_THREAD == 4) && (stride == 1) &&
                         valid_iw[0] && valid_iw[3];
  const bool can_vec4_out = (OW_PER_THREAD == 4) &&
                             valid_ow[0] && valid_ow[1] && valid_ow[2] && valid_ow[3];
  const int oh_tile_start = oh_tile_idx * OH_TILE;
  const int ih_tile_start = oh_tile_start * stride - padding;
  const int c_base = c_tile * CcPerBlock;
  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sYn = (int64_t)C * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  int cur = 0;
  {
    const int c0 = c_base;
    if (c0 < C) {
      const T* Xc0 = X + (int64_t)n * sXn + (int64_t)c0 * sXc;
      for (int ih_local = oh_group; ih_local < IH_TILE; ih_local += oh_threads) {
        int ih = ih_tile_start + ih_local;
        bool ih_ok = (ih >= 0 && ih < H);
        T* sdst = sX + (int64_t)cur * IH_TILE * OW_TILE + (int64_t)ih_local * OW_TILE + ow_local[0];
        if (can_vec4 && ih_ok) {
          const T* src = Xc0 + (int64_t)ih * Win + iw[0];
          if ((((uintptr_t)src) & 15u) == 0 && (((uintptr_t)sdst) & 15u) == 0) {
            *reinterpret_cast<float4*>(sdst) = *reinterpret_cast<const float4*>(src);
          } else {
            #pragma unroll
            for (int i = 0; i < 4; ++i) sdst[i] = src[i];
          }
        } else {
          #pragma unroll
          for (int i = 0; i < MAX_OW_PER_THREAD; ++i) {
            if (i < OW_PER_THREAD) {
              T val = T(0);
              if (valid_iw[i] && ih_ok) {
                val = Xc0[(int64_t)ih * Win + iw[i]];
              }
              sdst[i] = val;
            }
          }
        }
      }
    }
  }
  __syncthreads();
  const int oh_per_thread = (OH_TILE + oh_threads - 1) / oh_threads;
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    const int c = c_base + cc;
    if (c >= C) break;
    const int next = cur ^ 1;
    const int c_next = c_base + cc + 1;
    if (cc + 1 < CcPerBlock && c_next < C) {
      const T* Xcn = X + (int64_t)n * sXn + (int64_t)c_next * sXc;
      for (int ih_local = oh_group; ih_local < IH_TILE; ih_local += oh_threads) {
        int ih = ih_tile_start + ih_local;
        bool ih_ok = (ih >= 0 && ih < H);
        T* sdst = sX + (int64_t)next * IH_TILE * OW_TILE + (int64_t)ih_local * OW_TILE + ow_local[0];
        if (can_vec4 && ih_ok) {
          const T* src = Xcn + (int64_t)ih * Win + iw[0];
          if ((((uintptr_t)src) & 15u) == 0 && (((uintptr_t)sdst) & 15u) == 0) {
            *reinterpret_cast<float4*>(sdst) = *reinterpret_cast<const float4*>(src);
          } else {
            #pragma unroll
            for (int i = 0; i < 4; ++i) sdst[i] = src[i];
          }
        } else {
          #pragma unroll
          for (int i = 0; i < MAX_OW_PER_THREAD; ++i) {
            if (i < OW_PER_THREAD) {
              T val = T(0);
              if (valid_iw[i] && ih_ok) {
                val = Xcn[(int64_t)ih * Win + iw[i]];
              }
              sdst[i] = val;
            }
          }
        }
      }
    }
    float bval = 0.0f;
    if (B != nullptr) {
      bval = (float)B[c];
    }
    const T* Wc = W + (int64_t)c * K;
    const T* sXcur = sX + (int64_t)cur * IH_TILE * OW_TILE;
    #pragma unroll 4
    for (int t = 0; t < oh_per_thread; ++t) {
      int oh_local = t * oh_threads + oh_group;
      if (oh_local >= OH_TILE) break;
      int oh = oh_tile_start + oh_local;
      if (oh >= Hout) break;
      float acc[MAX_OW_PER_THREAD];
      #pragma unroll
      for (int i = 0; i < MAX_OW_PER_THREAD; ++i) acc[i] = bval;
      #pragma unroll
      for (int k = 0; k < K; ++k) {
        int ih_local = oh_local * stride + k * dilation;
        float wv = (float)Wc[k];
        const T* srow = sXcur + (int64_t)ih_local * OW_TILE;
        if (OW_PER_THREAD == 4) {
          float4 xv4 = *reinterpret_cast<const float4*>(srow + ow_local[0]);
          acc[0] += xv4.x * wv;
          acc[1] += xv4.y * wv;
          acc[2] += xv4.z * wv;
          acc[3] += xv4.w * wv;
        } else {
          #pragma unroll
          for (int i = 0; i < MAX_OW_PER_THREAD; ++i) {
            if (i < OW_PER_THREAD) {
              float xv = (float)srow[ow_local[i]];
              acc[i] += xv * wv;
            }
          }
        }
      }
      if (can_vec4_out) {
        T* Ybase = Y + (int64_t)n * sYn + (int64_t)c * sYc + (int64_t)oh * Wout + ow[0];
        if ((((uintptr_t)Ybase) & 15u) == 0) {
          float4 outv = make_float4(acc[0], acc[1], acc[2], acc[3]);
          *reinterpret_cast<float4*>(Ybase) = outv;
        } else {
          #pragma unroll
          for (int i = 0; i < 4; ++i) Ybase[i] = static_cast<T>(acc[i]);
        }
      } else {
        #pragma unroll
        for (int i = 0; i < MAX_OW_PER_THREAD; ++i) {
          if (i < OW_PER_THREAD && valid_ow[i]) {
            T* Yptr = Y + (int64_t)n * sYn + (int64_t)c * sYc + (int64_t)oh * Wout + ow[i];
            *Yptr = static_cast<T>(acc[i]);
          }
        }
      }
    }
    __syncthreads();
    cur = next;
  }
}
torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [C, 1, K, 1] for depthwise conv (groups=C)");
  int64_t N   = x.size(0);
  int64_t C   = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);
  TORCH_CHECK(w.size(0) == C, "w.size(0) must equal C");
  TORCH_CHECK(w.size(1) == 1, "w.size(1) must be 1 for depthwise");
  TORCH_CHECK(w.size(3) == 1, "w.size(3) must be 1 for (kernel_width=1)");
  int64_t K = w.size(2);
  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (1 - 1) - 1) / stride + 1; // kw=1
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C, "bias must be [C]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, C, Hout, Wout}, x.options());
  constexpr int OH_TILE       = 32;
  constexpr int OW_THREADS    = 64;
  constexpr int OW_PER_THREAD = 4;
  constexpr int OW_TILE       = OW_THREADS * OW_PER_THREAD;
  constexpr int OH_THREADS    = 4;
  constexpr int CcPerBlock    = 4;
  const int IH_TILE = (int)((OH_TILE - 1) * stride + (K - 1) * dilation + 1);
  const int64_t ow_tiles = (Wout + OW_TILE - 1) / OW_TILE;
  const int64_t oh_tiles = (Hout + OH_TILE - 1) / OH_TILE;
  const int64_t c_tiles  = (C + CcPerBlock - 1) / CcPerBlock;
  dim3 block(OW_THREADS, OH_THREADS);
  dim3 grid(
      (unsigned)ow_tiles,
      (unsigned)oh_tiles,
      (unsigned)(N * c_tiles)
  );
  size_t smem_bytes = (size_t)2 * (size_t)IH_TILE * (size_t)OW_TILE * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(
        dwconv2d_k1_kernel_tiled<float>,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)smem_bytes);
  }
  dwconv2d_k1_kernel_tiled<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)Win,
      (int)K, (int)stride, (int)padding, (int)dilation,
      (int)Hout, (int)Wout,
      OH_TILE, OW_TILE, IH_TILE,
      (int)c_tiles, CcPerBlock, OW_PER_THREAD
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "dwconv2d_k1_kernel_tiled launch failed: ", cudaGetErrorString(err));
  return y;
}
"""
dwconv2d_ext = load_inline(
    name="cute_dwconv2d_k1_ext_v2",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["dwconv2d_depthwise_k1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)
class ModelNew(nn.Module):
    """
    Depthwise 2D convolution with vertical asymmetric kernel (kernel_size x 1),
    implemented with a single custom CUDA kernel using CuTe.
    """
    def __init__(self,
                 in_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 bias: bool = False) -> None:
        super().__init__()
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert isinstance(stride, int) and stride >= 1
        assert isinstance(padding, int) and padding >= 0
        assert isinstance(dilation, int) and dilation >= 1
        self.in_channels = int(in_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        # Depthwise: groups = in_channels, out_channels = in_channels
        C = self.in_channels
        K = self.kernel_size
        # Weight shape matches PyTorch depthwise layout: [C_out, C_in/groups, Kh, Kw] with groups=C => [C,1,K,1]
        self.weight = nn.Parameter(torch.empty(C, 1, K, 1))
        if bias:
            self.bias = nn.Parameter(torch.empty(C))
        else:
            self.register_parameter("bias", None)
        self.reset_parameters()
        self._ext = dwconv2d_ext
    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.kernel_size  # depthwise per-channel fan_in equals kernel_size along H (Kw=1)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.dwconv2d_depthwise_k1_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
        )

