// final shared->global output stores to be issued as single 128-bit
// (float4) vectorized memory transactions instead of 4 separate 32-bit
// transactions, cutting instruction count and improving memory
// throughput, while falling back to the original scalar per-element path
// whenever the contiguous vectorized access is not valid (tile edges,
// non-unit stride, or unaligned addresses), preserving exact semantics.
template <typename T>
__global__ void dwconv2d_k1_kernel_tiled(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
