  const int oh_group     = threadIdx.y;
  const int oh_threads   = blockDim.y;
  const int ow_threads   = blockDim.x;
  const int ow_tile_idx  = blockIdx.x;
  const int oh_tile_idx  = blockIdx.y;
  const int zc     = blockIdx.z;
  const int c_tile = zc % CTiles;
  const int n      = zc / CTiles;
  constexpr int MAX_OW_PER_THREAD = 4; // must be >= host-side OW_PER_THREAD
  int ow_local[MAX_OW_PER_THREAD];
  int ow[MAX_OW_PER_THREAD];
  bool valid_ow[MAX_OW_PER_THREAD];
  int iw[MAX_OW_PER_THREAD];
  bool valid_iw[MAX_OW_PER_THREAD];
  #pragma unroll
  for (int i = 0; i < MAX_OW_PER_THREAD; ++i) {
    if (i < OW_PER_THREAD) {
      // Contiguous per-thread output-column mapping: enables vectorized
      // (float4) global/shared-memory accesses since a thread's
      // OW_PER_THREAD columns are now adjacent instead of strided.
      ow_local[i] = ow_local0 * OW_PER_THREAD + i;
      ow[i] = ow_tile_idx * OW_TILE + ow_local[i];
      valid_ow[i] = (ow[i] < Wout);
      if (valid_ow[i]) {
        iw[i] = ow[i] * stride - padding;
        valid_iw[i] = (iw[i] >= 0 && iw[i] < Win);
      } else {
        iw[i] = 0;
        valid_iw[i] = false;
      }
    } else {
      ow_local[i] = 0; ow[i] = 0; valid_ow[i] = false; iw[i] = 0; valid_iw[i] = false;
