  {
    const int c0 = c_base;
    if (c0 < C) {
      const T* Xc0 = X + (int64_t)n * sXn + (int64_t)c0 * sXc;
      for (int ih_local = oh_group; ih_local < IH_TILE; ih_local += oh_threads) {
        int ih = ih_tile_start + ih_local;
        bool ih_ok = (ih >= 0 && ih < H);
        T* sdst = sX + (int64_t)cur * IH_TILE * OW_TILE + (int64_t)ih_local * OW_TILE + ow_local[0];
        if (can_vec4 && ih_ok) {
