  const int oh_per_thread = (OH_TILE + oh_threads - 1) / oh_threads;
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    const int c = c_base + cc;
    if (c >= C) break;
    const int next = cur ^ 1;
    const int c_next = c_base + cc + 1;
    if (cc + 1 < CcPerBlock && c_next < C) {
      const T* Xcn = X + (int64_t)n * sXn + (int64_t)c_next * sXc;
