        int ih = ih_tile_start + ih_local;
        bool ih_ok = (ih >= 0 && ih < H);
        T* sdst = sX + (int64_t)next * IH_TILE * OW_TILE + (int64_t)ih_local * OW_TILE + ow_local[0];
